import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.C-si7TFR.js";const g=JSON.parse('{"title":"Redis 触发器","description":"通过监听 Redis 列表的 LPUSH/RPUSH 操作来触发工作流，支持实时消息驱动。","frontmatter":{"title":"Redis 触发器","description":"通过监听 Redis 列表的 LPUSH/RPUSH 操作来触发工作流，支持实时消息驱动。","meta":[{"name":"keywords","content":"Redis, 触发器, LPUSH, RPUSH, 列表, 消息队列, 低代码, AI工作流, 流程引擎"}]},"headers":[],"relativePath":"zh/trigger_redis.md","filePath":"zh/trigger_redis.md"}'),d={name:"zh/trigger_redis.md"};function r(l,e,o,n,h,p){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h2 id="redis-触发器" tabindex="-1">Redis 触发器 <a class="header-anchor" href="#redis-触发器" aria-label="Permalink to &quot;Redis 触发器&quot;">​</a></h2><p>通过监听 Redis 列表的新增数据来触发工作流。当数据通过 <code>LPUSH</code> 或 <code>RPUSH</code> 被推送到指定的 Redis 列表键时，工作流会自动执行。适用于构建消息驱动的工作流、任务队列和实时事件处理。</p><h2 id="入参" tabindex="-1">入参 <a class="header-anchor" href="#入参" aria-label="Permalink to &quot;入参&quot;">​</a></h2><ul><li><p><strong>凭据</strong>（必填）：选择一个 Redis 凭据。可在【应用开发】&gt;【凭据管理】中创建 Redis 凭据类型，需配置以下选项：</p><ul><li><strong>Host</strong>：Redis 服务器地址。</li><li><strong>Port</strong>：Redis 服务器端口（默认：6379）。</li><li><strong>Auth</strong>：Redis 认证密码（可选）。</li></ul></li><li><p><strong>Method</strong>（必填）：要监听的 Redis 列表操作方式。支持：</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td>lpush</td><td>监听从列表左侧推入的数据（LPUSH 操作）</td></tr><tr><td>rpush</td><td>监听从列表右侧推入的数据（RPUSH 操作）</td></tr></tbody></table></li><li><p><strong>Select</strong>（必填）：Redis 数据库索引（从 0 开始，必须 ≥ 0）。</p></li><li><p><strong>Key</strong>（必填）：要监听的 Redis 列表键名。</p></li></ul><h2 id="出参" tabindex="-1">出参 <a class="header-anchor" href="#出参" aria-label="Permalink to &quot;出参&quot;">​</a></h2><p>每次有新数据被推送到指定的 Redis 列表时，工作流将被触发，推送的数据作为输出。输出为推送数据解析后的 JSON 内容。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pushed-value&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><blockquote><p>实际输出格式取决于推送到 Redis 列表中的数据内容。</p></blockquote><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ol><li>当工作流启用时，IOLinker 连接到 Redis 服务器并监听指定的列表键。</li><li>当有新数据通过 <code>LPUSH</code> 或 <code>RPUSH</code>（取决于配置的方法）推送到列表时，该数据会被消费并触发工作流。</li><li>每条推送的数据触发一次独立的工作流执行，数据内容作为触发器输出。</li><li>数据从列表中被消费（弹出），因此不会重复触发工作流。</li></ol>`,10)])])}const u=t(d,[["render",r]]);export{g as __pageData,u as default};
